import{_ as e,C as i,c as a,o as s,a9 as r,G as t}from"./chunks/framework.DuenUNqn.js";const h=JSON.parse('{"title":"更新 Towny","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"TownyAdvanced","link":"/wiki/TownyAdvanced"},{"title":"setup","link":""},{"title":"更新 Towny","link":"/wiki/TownyAdvanced/setup/updating-towny"}]},"headers":[],"relativePath":"wiki/TownyAdvanced/setup/updating-towny.md","filePath":"wiki/TownyAdvanced/setup/updating-towny.md"}'),u={name:"wiki/TownyAdvanced/setup/updating-towny.md"};function d(c,l,w,p,y,_){const o=i("NolebaseGitContributors"),n=i("NolebaseGitChangelog");return s(),a("div",null,[l[0]||(l[0]=r('<h1 id="更新-towny" tabindex="-1">更新 Towny <a class="header-anchor" href="#更新-towny" aria-label="Permalink to &quot;更新 Towny&quot;">​</a></h1><p>本章将会讲述如何从旧版 Towny 更新。</p><h2 id="更新步骤" tabindex="-1">更新步骤 <a class="header-anchor" href="#更新步骤" aria-label="Permalink to &quot;更新步骤&quot;">​</a></h2><ol><li>关闭服务器。</li><li>备份整个服务器！</li></ol><ul><li>如果你以配置文件形式存储 Towny 数据，Towny 会自行备份（不包含世界内的方块！仍需要完整备份。）</li><li>可能需要从 <code>plugins\\towny\\backups\\</code> 文件夹中找到最新的 .zip 备份数据并将其移动到其他安全的地方。</li></ul><ol start="3"><li>下载 Towny_Advanced.zip，并解压获得 .jar 文件，将其放入 plugins 文件夹中。</li></ol><ul><li>确保你已经删除了插件文件夹中安装的旧版 Towny。</li></ul><ol start="4"><li>浏览更新日志或发行版页面获悉新内容。</li></ol><ul><li>更新日志中包含了需要手动更改的内容（不过现在比较少见。）</li><li>其他配置改动（如新设置）会自动加入文件。 <ul><li>新增的设置通常为其默认值。</li></ul></li><li><strong>无需每次更新时都删除/编辑 Towny 的配置文件。</strong></li></ul><ol start="5"><li>启动服务器。</li><li>按需调整新增配置。</li><li>关闭服务器。</li></ol><h2 id="特殊操作步骤" tabindex="-1">特殊操作步骤 <a class="header-anchor" href="#特殊操作步骤" aria-label="Permalink to &quot;特殊操作步骤&quot;">​</a></h2><ul><li>若从低于 0.79.0.0 的版本更新： <ul><li>config.yml 的 chat 部分已经独立为新文件 channels.yml。只需编辑新文件中的设置即可。</li></ul></li><li>若从低于 0.82.0.0 的版本更新： <ul><li>Towny 新增了 TownyPerms。新增了一个位于 townysettings 下的 townyperms.yml 文件，首次启动服务器时自动生成。 <ul><li>这个模块向服务器添加了城镇及国家等级，管理员可手动指定各个等级的权限（游民、居民、城镇拥有者、国家领袖等）。除此之外，管理员也可以创建自定义等级，设置自定义权限。设置为助理的玩家会失去当前等级，需要重新为其分配权限。</li></ul></li></ul></li></ul>',12)),t(o),t(n)])}const m=e(u,[["render",d]]);export{h as __pageData,m as default};
